export interface BillingApi {                 // client-facing delegate contract
  createInvoice(cmd: CreateInvoice): Promise<Invoice>;
}
export class HttpBillingApi implements BillingApi {
  constructor(private http: HttpClient, private base: string) {}
  async createInvoice(cmd: CreateInvoice): Promise<Invoice> {
    const res = await this.http.post(`${this.base}/invoices`, cmd);
    if (!res.ok) throw new BillingError(res.status, await res.text());  // translate
    return (await res.json()) as Invoice;
  }
}
